def compute(vars):
    maturities_2012 = vars["v1"]
    total_cash_obligations = vars["v2"]

    if total_cash_obligations == 0:
        return None

    ratio = maturities_2012 / total_cash_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "maturities_2012": maturities_2012,
            "total_cash_obligations": total_cash_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
